    12	export function setting(name, env = process.env) {
    13	  const fromEnv = env[name];
    14	  if (typeof fromEnv === 'string' && fromEnv !== '') return fromEnv;
    15	  if (env.CONFIG_DIR) {
    16	    try {
    17	      const fromFile = readFileSync(join(env.CONFIG_DIR, name), 'utf8').trim();
    18	      if (fromFile) return fromFile;
    19	    } catch {
    20	      // not mounted: fall through to the default
    21	    }
    22	  }
    23	  return DEFAULTS[name];
