     1	import { timingSafeEqual, createHmac } from 'node:crypto';
     2	import { setting } from '../config/settings.js';
     3	
     4	// The key partners sign their webhook calls with. It always comes from outside; see docs/hook-signing.md.
     5	export function readSigningKey(env = process.env) {
     6	  const v = setting('HOOK_SIGNING_KEY', env);
     7	  return typeof v === 'string' && v.trim() ? v.trim() : null;
     8	}
     9	
    10	const LEGACY = /^v1:/;
    11	
    12	// Called once at start-up (src/server.js). In production a missing or legacy key stops the start.
    13	export function assertSigningKeyConfigured(env = process.env) {
    14	  const key = readSigningKey(env);
    15	  if (env.NODE_ENV !== 'production') return key;
    16	  if (!key) throw new Error('[hooks] HOOK_SIGNING_KEY is required in production');
    17	  if (LEGACY.test(key)) throw new Error('[hooks] a v1: signing key is not accepted in production');
    18	  return key;
    19	}
    20	
    21	export function sign(body, key) {
    22	  return createHmac('sha256', key).update(body).digest('hex');
    23	}
    24	
    25	export function verify(body, signature, key) {
    26	  if (!key || typeof signature !== 'string') return false;
    27	  const want = Buffer.from(sign(body, key), 'hex');
    28	  const got = Buffer.from(signature, 'hex');
    29	  return want.length === got.length && timingSafeEqual(want, got);
    30	}
